    overflow-y: auto;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
    border: 1px solid #e9ecef;
}

.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    min-height: 180px;
