    }

    .settings-sidebar .nav-link {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
    }

    .settings-sidebar .nav-link.active {
        border-left-color: transparent;
        border-bottom-color: #0d6efd;
    }
}

toolCalls.args:
{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_6e26b7152e9c447c9ab25d55da1b790a.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="section-icon">@section.Value.Icon</span>
                        @section.Value.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@if (_toastVisible)
{
    <div class="settings-toast @(_toastIsError ? "toast-error" : "toast-success")">
        @_toastMessage
    </div>
}

@if (_showRevokeDialog)
{
    <div class="modal-backdrop show"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_revokeSessionDevice</strong>?</p>
                    <p class="text-muted mb-0">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private bool _toastVisible;
    private string _toastMessage = "";
    private bool _toastIsError;

    // Profile state
    private string _profileName = "";
    private string _profileEmail = "";
    private string _profileBio = "";
    private string _profileAvatarUrl = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = [];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _showRevokeDialog;
    private string? _revokeSessionId;
    private string _revokeSessionDevice = "";

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private readonly string[] _availableLanguages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        var profile = profileTask.Result;
        _savedProfile = profile;
        _profileName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileBio = profile.Bio;
        _profileAvatarUrl = profile.AvatarUrl;

        var notif = notifTask.Result;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _allChannels = new List<string>(notif.MutedChannels.Count > 0
            ? notif.MutedChannels
            : ["general", "random", "announcements"]);
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        _security = securityTask.Result;
        _twoFactorEnabled = _security.TwoFactorEnabled;

        var appearance = appearanceTask.Result;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    // --- Toast ---
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
        _toastVisible = true;
        StateHasChanged();
        await Task.Delay(3000);
        _toastVisible = false;
        StateHasChanged();
    }

    // --- Profile ---
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            _profileName = _savedProfile.DisplayName;
            _profileEmail = _savedProfile.Email;
            _profileBio = _savedProfile.Bio;
            _profileAvatarUrl = _savedProfile.AvatarUrl;
        }
    }

    // --- Notifications ---
    private void ToggleMutedChannel(string channel)
    {
        if (!_mutedChannels.Remove(channel))
        {
            _mutedChannels.Add(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // --- Security ---
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword)
            || string.IsNullOrWhiteSpace(_newPassword)
            || string.IsNullOrWhiteSpace(_confirmPassword))
        {
            await ShowToast("All password fields are required.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevoke(ActiveSession session)
    {
        _revokeSessionId = session.Id;
        _revokeSessionDevice = session.Device;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _revokeSessionId = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_revokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(_revokeSessionId);
            _security = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _revokeSessionId = null;
        await ShowToast("Session revoked.");
    }

    // --- Appearance ---
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewBackground => _theme switch
    {
        "Dark" => "#1e1e2e",
        "System" => "#f0f0f5",
        _ => "#ffffff"
    };

    private string PreviewTextColor => _theme switch
    {
        "Dark" => "#cdd6f4",
        _ => "#212529"
    };

    // --- Render fragments ---

    private RenderFragment RenderProfile() => __builder =>
    {
        <h4 class="section-heading">Profile</h4>
        <div class="card settings-card">
            <div class="card-body">
                <div class="row">
                    <div class="col-md-8">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Display Name</label>
                            <input type="text" class="form-control" @bind="_profileName" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Email</label>
                            <input type="email" class="form-control" @bind="_profileEmail" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Bio</label>
                            <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
                        </div>
                    </div>
                    <div class="col-md-4 text-center">
                        <label class="form-label fw-semibold d-block">Avatar Preview</label>
                        <div class="avatar-preview mb-2">
                            <img src="@_profileAvatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120" />
                        </div>
                        <small class="text-muted text-break">@_profileAvatarUrl</small>
                    </div>
                </div>
                <hr />
                <div class="d-flex gap-2">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    };

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h4 class="section-heading">Notifications</h4>
        <div class="card settings-card">
            <div class="card-body">
                <div class="mb-3">
                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
                        <label class="form-check-label" for="emailNotif">Email Notifications</label>
                    </div>
                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
                        <label class="form-check-label" for="pushNotif">Push Notifications</label>
                    </div>
                    <div class="form-check form-switch mb-2">
                        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
                        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                    </div>
                </div>
                <hr />
                <h6 class="fw-semibold mb-3">Muted Channels</h6>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var channelId = $"ch-{channel}";
                        var isMuted = _mutedChannels.Contains(channel);
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@channelId"
                                   checked="@isMuted"
                                   @onchange="() => ToggleMutedChannel(channel)" />
                            <label class="form-check-label" for="@channelId">
                                #@channel
                                @if (isMuted)
                                {
                                    <span class="badge bg-secondary ms-2">Muted</span>
                                }
                            </label>
                        </div>
                    }
                </div>
                <hr />
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h4 class="section-heading">Security</h4>

        <!-- Change Password -->
        <div class="card settings-card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor: pointer"
                 @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span class="fw-semibold">Change Password</span>
                <span>@(_passwordPanelOpen ? "▲" : "▼")</span>
            </div>
            @if (_passwordPanelOpen)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    @if (_security?.LastPasswordChange is not null)
                    {
                        <small class="text-muted ms-3">
                            Last changed: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </small>
                    }
                </div>
            }
        </div>

        <!-- Two-Factor -->
        <div class="card settings-card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="fw-semibold mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>
        </div>

        <!-- Active Sessions -->
        <div class="card settings-card">
            <div class="card-body">
                <h6 class="fw-semibold mb-3">Active Sessions</h6>
                @if (_security?.Sessions.Count > 0)
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _security.Sessions)
                                {
                                    var isCurrentSession = session == _security.Sessions[0];
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isCurrentSession)
                                            {
                                                <span class="badge bg-info ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@FormatLastActive(session.LastActive)</td>
                                        <td>
                                            @if (!isCurrentSession)
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => RequestRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted mb-0">No active sessions.</p>
                }
            </div>
        </div>
    };

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h4 class="section-heading">Appearance</h4>
        <div class="card settings-card mb-3">
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <!-- Theme -->
                        <div class="mb-4">
                            <label class="form-label fw-semibold">Theme</label>
                            <div>
                                @foreach (var theme in new[] { "Light", "Dark", "System" })
                                {
                                    var themeId = $"theme-{theme.ToLowerInvariant()}";
                                    <div class="form-check form-check-inline">
                                        <input class="form-check-input" type="radio" name="theme"
                                               id="@themeId" value="@theme"
                                               checked="@(_theme == theme)"
                                               @onchange="() => _theme = theme" />
                                        <label class="form-check-label" for="@themeId">@theme</label>
                                    </div>
                                }
                            </div>
                        </div>

                        <!-- Font Size -->
                        <div class="mb-4">
                            <label class="form-label fw-semibold">Font Size</label>
                            <div>
                                @foreach (var size in new[] { "Small", "Medium", "Large" })
                                {
                                    var sizeId = $"fs-{size.ToLowerInvariant()}";
                                    <div class="form-check form-check-inline">
                                        <input class="form-check-input" type="radio" name="fontSize"
                                               id="@sizeId" value="@size"
                                               checked="@(_fontSize == size)"
                                               @onchange="() => _fontSize = size" />
                                        <label class="form-check-label" for="@sizeId">@size</label>
                                    </div>
                                }
                            </div>
                        </div>

                        <!-- Language -->
                        <div class="mb-4">
                            <label class="form-label fw-semibold">Language</label>
                            <select class="form-select" @bind="_language">
                                @foreach (var lang in _availableLanguages)
                                {
                                    <option value="@lang">@lang</option>
                                }
                            </select>
                        </div>

                        <!-- Compact Mode -->
                        <div class="mb-3">
                            <div class="form-check form-switch">
                                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                                <label class="form-check-label" for="compactMode">Compact Mode</label>
                            </div>
                        </div>
                    </div>

                    <div class="col-md-6">
                        <!-- Live Preview -->
                        <label class="form-label fw-semibold">Live Preview</label>
                        <div class="appearance-preview"
                             style="background: @PreviewBackground; color: @PreviewTextColor; font-size: @PreviewFontSize; padding: @(_compactMode ? "0.75rem" : "1.25rem");">
                            <h6 style="color: @PreviewTextColor; margin-bottom: @(_compactMode ? "0.25rem" : "0.5rem");">
                                Dashboard
                            </h6>
                            <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem");">
                                Welcome back! Here's your summary for today.
                            </p>
                            <div class="d-flex gap-2 flex-wrap">
                                <span class="badge bg-primary">12 Tasks</span>
                                <span class="badge bg-success">3 Completed</span>
                                <span class="badge bg-warning text-dark">2 Pending</span>
                            </div>
                            <hr style="border-color: @(_theme == "Dark" ? "#444" : "#ddd");" />
                            <small>Theme: @_theme · Font: @_fontSize · Lang: @_language · Compact: @(_compactMode ? "On" : "Off")</small>
                        </div>
                    </div>
                </div>
                <hr />
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>
    };
}
